package com.cqutcm.biomed.controller;import com.cqutcm.biomed.service.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/mobile") public class MobileCollectionController{private final AuthService auth;private final MobileCollectionService service;public MobileCollectionController(AuthService a,MobileCollectionService s){auth=a;service=s;}@GetMapping("/devices")public Map<String,Object>devices(@RequestHeader(value="Authorization",required=false)String t){return Map.of("items",service.devices(auth.requireActor(t)));}@PostMapping("/devices")public Map<String,Object>register(@RequestBody Map<String,Object>b,@RequestHeader(value="Authorization",required=false)String t){return service.register(b,auth.requireActor(t));}@PostMapping("/devices/{id}/rotate-token")public Map<String,Object>rotate(@PathVariable String id,@RequestHeader(value="Authorization",required=false)String t){return service.rotate(id,auth.requireActor(t));}@PutMapping("/devices/{id}/status")public Map<String,Object>status(@PathVariable String id,@RequestBody Map<String,Object>b,@RequestHeader(value="Authorization",required=false)String t){service.setStatus(id,String.valueOf(b.get("status")),auth.requireActor(t));return Map.of("message","status updated");}@PostMapping("/growth-records/batch")public Map<String,Object>ingest(@RequestHeader(value="X-Device-Token",required=false)String token,@RequestBody Map<String,List<Map<String,Object>>>b){return service.ingest(token,b.get("records"));}@GetMapping("/sync/status")public Map<String,Object>sync(@RequestHeader(value="X-Device-Token",required=false)String token){return service.syncStatus(token);}}
